import { createContext } from "svelte";

export class WheelPickerGroupState {
	activeIndex = $state(-1);

	#nextIndex = 0;
	#pickerRefs = new Map<number, HTMLDivElement>();

	register(ref: HTMLDivElement): number {
		const index = this.#nextIndex++;
		this.#pickerRefs.set(index, ref);

		if (this.activeIndex === -1) {
			this.activeIndex = index;
		}

		return index;
	}

	unregister(index: number, ref: HTMLDivElement): void {
		if (this.#pickerRefs.get(index) !== ref) return;

		this.#pickerRefs.delete(index);

		if (this.activeIndex === index) {
			this.activeIndex = this.getPickerIndices()[0] ?? -1;
		}
	}

	setActiveIndex(index: number): void {
		if (this.#pickerRefs.has(index)) {
			this.activeIndex = index;
		}
	}

	getPickerRef(index: number): HTMLDivElement | null {
		return this.#pickerRefs.get(index) ?? null;
	}

	getPickerIndices(): number[] {
		return [...this.#pickerRefs.keys()].sort((a, b) => a - b);
	}
}

const [getWheelPickerGroupContext, setWheelPickerGroupContext] =
	createContext<WheelPickerGroupState>();

export function provideWheelPickerGroup(): WheelPickerGroupState {
	const group = new WheelPickerGroupState();
	setWheelPickerGroupContext(group);
	return group;
}

export function useWheelPickerGroup(): WheelPickerGroupState | null {
	try {
		return getWheelPickerGroupContext();
	} catch {
		return null;
	}
}

const TYPEAHEAD_TIMEOUT_MS = 500;

type TypeaheadSearchOptions<T> = {
	getOptions: () => T[];
	getTextValue: (option: T) => string;
	getCurrentIndex: () => number;
	onMatch: (index: number) => void;
};

export function createTypeaheadSearch<T>({
	getOptions,
	getTextValue,
	getCurrentIndex,
	onMatch
}: TypeaheadSearchOptions<T>) {
	let searchBuffer = "";
	let timeout: ReturnType<typeof setTimeout> | null = null;

	function reset(): void {
		searchBuffer = "";

		if (timeout) {
			clearTimeout(timeout);
			timeout = null;
		}
	}

	function search(character: string): void {
		const options = getOptions();
		if (options.length === 0) return;

		if (timeout) clearTimeout(timeout);

		searchBuffer += character.toLocaleLowerCase();
		const repeated =
			searchBuffer.length > 1 &&
			[...searchBuffer].every(
				(searchCharacter) => searchCharacter === searchBuffer[0]
			);
		const searchTerm = repeated ? searchBuffer[0] : searchBuffer;

		let matchIndex = -1;

		if (searchTerm.length === 1) {
			const currentIndex = getCurrentIndex();

			for (let offset = 1; offset <= options.length; offset += 1) {
				const index = (currentIndex + offset) % options.length;
				if (
					getTextValue(options[index])
						.toLocaleLowerCase()
						.startsWith(searchTerm)
				) {
					matchIndex = index;
					break;
				}
			}
		} else {
			matchIndex = options.findIndex((option) =>
				getTextValue(option).toLocaleLowerCase().startsWith(searchTerm)
			);
		}

		if (matchIndex !== -1) onMatch(matchIndex);

		timeout = setTimeout(reset, TYPEAHEAD_TIMEOUT_MS);
	}

	return { search, reset };
}

import type { Snippet } from "svelte";
import type { HTMLAttributes } from "svelte/elements";

export type WheelPickerValue = string | number;

export type WheelPickerLabel = string | number | Snippet;

export type WheelPickerOption<T extends WheelPickerValue = string> = {
	/** Value returned when this option is selected. */
	value: T;
	/** Text or a Svelte snippet rendered for this option. */
	label: WheelPickerLabel;
	/** Text used by typeahead search. Falls back to a text label or the value. */
	textValue?: string;
	/** Prevents the option from being selected. */
	disabled?: boolean;
};

export type WheelPickerClasses = {
	optionItem?: string;
	highlightWrapper?: string;
	highlightItem?: string;
};

export type WheelPickerProps<T extends WheelPickerValue = string> = Omit<
	HTMLAttributes<HTMLDivElement>,
	"children" | "onblur" | "onfocus" | "onkeydown" | "onwheel"
> & {
	/** Bindable selected value. */
	value?: T;
	/** Initial value used when `value` is undefined. */
	defaultValue?: T;
	/** Called whenever interaction selects a different value. */
	onValueChange?: (value: T) => void;
	options: WheelPickerOption<T>[];
	/** @default false */
	infinite?: boolean;
	/** Number of positions around the wheel. Must be a positive multiple of four. @default 20 */
	visibleCount?: number;
	/** @default 3 */
	dragSensitivity?: number;
	/** @default 5 */
	scrollSensitivity?: number;
	/** @default 30 */
	optionItemHeight?: number;
	classes?: WheelPickerClasses;
	/** Bindable reference to the picker element. */
	ref?: HTMLDivElement | null;
};

export type WheelPickerWrapperProps = Omit<
	HTMLAttributes<HTMLDivElement>,
	"children"
> & {
	children: Snippet;
	/** Bindable reference to the wrapper element. */
	ref?: HTMLDivElement | null;
};

import type { WheelPickerOption, WheelPickerValue } from "./wheel-picker-types";

export const RESISTANCE = 0.3;
export const MAX_VELOCITY = 30;

export function easeOutCubic(progress: number): number {
	return Math.pow(progress - 1, 3) + 1;
}

export function clamp(value: number, min: number, max: number): number {
	return Math.max(min, Math.min(value, max));
}

export function getOptionTextValue<T extends WheelPickerValue>(
	option: WheelPickerOption<T>
): string {
	return (
		option.textValue ??
		(typeof option.label === "string"
			? option.label
			: typeof option.label === "number"
				? String(option.label)
				: String(option.value))
	);
}

export function findNearestEnabledIndex<T extends WheelPickerValue>(
	startIndex: number,
	direction: 1 | -1,
	options: WheelPickerOption<T>[],
	infinite: boolean
): number {
	if (options.length === 0 || !options.some((option) => !option.disabled)) {
		return startIndex;
	}

	const search = (nextDirection: 1 | -1): number => {
		let currentIndex = startIndex;

		for (let attempts = 0; attempts < options.length; attempts += 1) {
			currentIndex += nextDirection;

			if (infinite) {
				currentIndex = normalizeIndex(currentIndex, options.length);
			} else if (currentIndex < 0 || currentIndex >= options.length) {
				return -1;
			}

			if (!options[currentIndex]?.disabled) return currentIndex;
		}

		return -1;
	};

	const inDirection = search(direction);
	if (inDirection !== -1) return inDirection;

	const inOppositeDirection = search(direction === 1 ? -1 : 1);
	return inOppositeDirection === -1 ? startIndex : inOppositeDirection;
}

export function normalizeIndex(value: number, length: number): number {
	if (length === 0) return 0;
	return ((value % length) + length) % length;
}

export function validateVisibleCount(value: number): number {
	if (value > 0 && value % 4 === 0) return value;

	if (import.meta.env.DEV) {
		console.warn(
			`WheelPicker: visibleCount must be a positive multiple of 4. Received ${value}; using 20 instead.`
		);
	}

	return 20;
}

[data-wheel-picker-wrapper] ul {
	margin: 0;
	padding: 0;
	list-style: none;
}

[data-wheel-picker-wrapper] li {
	margin: 0;
	padding: 0;
}

[data-wheel-picker-wrapper] {
	position: relative;
	overflow: hidden;
	display: flex;
	width: 100%;
	align-items: stretch;
	justify-content: space-between;
	perspective: 2000px;
	user-select: none;
}

[data-wheel-picker] {
	position: relative;
	overflow: hidden;
	flex: 1;
	cursor: default;
	mask-image: linear-gradient(
		to bottom,
		transparent 0%,
		black 20%,
		black 80%,
		transparent 100%
	);
}

[data-wheel-picker]:focus-visible {
	outline: none;
}

[data-wheel-picker-highlight-wrapper] {
	position: absolute;
	overflow: hidden;
	top: 50%;
	width: 100%;
	transform: translateY(-50%);
	font-size: 1rem;
	font-weight: 500;
}

[data-wheel-picker-highlight-list] {
	position: absolute;
	width: 100%;
}

[data-wheel-picker-options] {
	position: absolute;
	top: 50%;
	left: 0;
	display: block;
	width: 100%;
	height: 0;
	margin: 0 auto;
	-webkit-font-smoothing: subpixel-antialiased;
	will-change: transform;
	backface-visibility: hidden;
	transform-style: preserve-3d;
}

[data-wheel-picker-option] {
	position: absolute;
	top: 0;
	left: 0;
	width: 100%;
	-webkit-font-smoothing: subpixel-antialiased;
	will-change: visibility;
	font-size: 0.875rem;
}

[data-wheel-picker-option],
[data-wheel-picker-highlight-item] {
	display: flex;
	align-items: center;
	justify-content: center;
}

[data-wheel-picker-option][data-disabled],
[data-wheel-picker-highlight-item][data-disabled] {
	pointer-events: none;
}

import WheelPicker from "./wheel-picker.svelte";
import WheelPickerWrapper from "./wheel-picker-wrapper.svelte";

export { WheelPicker, WheelPickerWrapper };

export type {
	WheelPickerClasses,
	WheelPickerLabel,
	WheelPickerOption,
	WheelPickerProps,
	WheelPickerValue,
	WheelPickerWrapperProps
} from "./wheel-picker-types";
